      "format": "package",
      "angle": "Explain the finding in plain language, clarify the evidence and uncertainty, and connect frontier science, research infrastructure and scientific discovery to China’s wider innovation capacity. For this item, test the claim behind “西安分院分党组召开理论学习中心组学习（扩大）会” against primary-source evidence.",
      "status": "confirmed_today",
      "matchedTopic": "科学前沿动态",
      "rawText": "首页 > 党建与科学文化 > 工作动态 7月13日，中国科学院西安分院分党组召开理论学习中心组学习（扩大）会议，深入学习领会习近平党建思想，传达学习习近平总书记在国家科学技术奖励大会、中国科学院第二十二次院士大会和中国工程院第十八次院士大会、中国科学技术协会第十一次全国代表大会（“科技三会”）上的重要讲话精神。 会上，西安分院分党组书记、系统单位党委书记詹瑞围绕习近平党建思想讲授专题党课，重温习近平总书记在庆祝中国共产党成立105周年大会上的重要讲话精神，传达习近平总书记在“科技三会”上的重要讲话精神。分院纪检组组长、分党组成员李晋芳领学《习近平党建文选》第二卷部分篇目并分享学习体会。分院院长、分党组副书记张首刚围绕习近平总书记在“科技三会”上的重要讲话精神，立足当前国家科技发展形势特点作重点发言。分院副院长王雷针对本次学习内容，紧扣最新科技与人才政策改革趋势，结合陕西省科学院管理举措和改革方向提出新思路。 会议指出，习近平党建思想内涵丰富、体系严密，鲜明提出“十四个坚持”，是对习近平总书记关于新时代党的建设具有标志性引领性的新理念新思想新战略的集中概括，是加强新时代党的建设的根本遵循",
      "relatedTitles": [
        "西安分院分党组召开理论学习中心组学习（扩大）会"
      ],
